export const ADMIN_HTML = "<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"robots\" content=\"noindex,nofollow\">\n<title>慧学星成绩单监控</title>\n<style>\n*{box-sizing:border-box}\nbody{margin:0;background:#0d1014;color:#e6edf3;font:14px/1.55 -apple-system,BlinkMacSystemFont,\"Segoe UI\",\"Microsoft YaHei\",sans-serif}\n.wrap{max-width:1180px;margin:0 auto;padding:18px 16px 60px}\nheader{display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding:10px 0 16px;border-bottom:1px solid #1e2530;margin-bottom:18px}\n.brand{font-size:17px;font-weight:650;letter-spacing:.3px}\n.spacer{flex:1}\nbutton{font:inherit;border-radius:7px;padding:6px 12px;cursor:pointer;border:1px solid #2b3440;background:#161c24;color:#d7e2ee;transition:.15s}\nbutton:hover{background:#1d2530;border-color:#3a4553}\nbutton.primary{background:#1f6feb;border-color:#1f6feb;color:#fff}\nbutton.primary:hover{background:#2b7ff5}\nbutton.danger:hover{border-color:#7a2f2f;color:#ff9b9b}\nbutton[disabled]{opacity:.5;cursor:not-allowed}\nbutton.full{width:100%;margin-top:10px;padding:9px}\n.pill{font-size:12px;padding:3px 10px;border-radius:999px;border:1px solid #2b3440;background:#151a21;color:#9fb0c1}\n.pill.ok{color:#7ee0a1;border-color:#245b3a;background:#12251a}\n.pill.warn{color:#ffd479;border-color:#5c4615;background:#231c0d}\n.pill.bad{color:#ff9b9b;border-color:#6a2b2b;background:#241313}\n.banner{margin:0 0 16px;padding:10px 14px;border-radius:9px;background:#231c0d;border:1px solid #5c4615;color:#ffd479;font-size:13px}\n.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px;margin-bottom:18px}\n.card{background:#12171e;border:1px solid #1e2530;border-radius:11px;padding:14px}\n.card .k{font-size:12px;color:#8b9aab;letter-spacing:.4px}\n.card .v{font-size:24px;font-weight:650;margin:4px 0 2px;font-variant-numeric:tabular-nums}\n.card .v.small{font-size:14px;font-weight:500;line-height:1.4}\n.card .s{font-size:11px;color:#6d7d8e}\n.panel{background:#12171e;border:1px solid #1e2530;border-radius:11px;padding:14px 16px;margin-bottom:16px}\n.panel h2{font-size:14px;margin:0 0 12px;font-weight:620;color:#c9d6e3}\n.tablewrap{overflow:auto;max-height:420px}\ntable{width:100%;border-collapse:collapse;font-size:13px}\nth{position:sticky;top:0;z-index:2;background:#12171e;text-align:left;font-weight:600;color:#8b9aab;font-size:12px;padding:8px 10px;border-bottom:1px solid #1e2530;white-space:nowrap}\ntd{padding:8px 10px;border-bottom:1px solid #161c24;vertical-align:top}\ntr:hover td{background:#151b23}\n.num{text-align:right;font-variant-numeric:tabular-nums}\n.score{font-weight:650;color:#8ad3ff}\n.null{color:#6d7d8e}\n.tag{display:inline-block;font-size:11px;padding:1px 7px;border-radius:999px;border:1px solid #2b3440;white-space:nowrap}\n.tag.new_report{color:#7ee0a1;border-color:#245b3a;background:#12251a}\n.tag.score_change{color:#8ad3ff;border-color:#1d4a6b;background:#0f1e2a}\n.tag.score_filled{color:#ffd479;border-color:#5c4615;background:#231c0d}\n.tag.score_cleared{color:#ff9b9b;border-color:#6a2b2b;background:#241313}\n.empty{font-size:13px;color:#6d7d8e;padding:6px 2px}\n.diag{background:#0b0f14;border:1px solid #1e2530;border-radius:9px;padding:12px;font-size:12px;line-height:1.5;white-space:pre-wrap;word-break:break-all;max-height:420px;overflow:auto;color:#a9bccf}\nfooter{margin-top:22px;font-size:12px;color:#5f6f80;border-top:1px solid #1e2530;padding-top:12px}\n.login{position:fixed;inset:0;background:rgba(8,10,14,.93);display:flex;align-items:center;justify-content:center;z-index:50}\n.loginbox{width:340px;background:#12171e;border:1px solid #26303c;border-radius:14px;padding:26px}\n.loginbox h1{font-size:18px;margin:0 0 6px}\n.muted{color:#8b9aab;font-size:12px;margin:0 0 14px}\n.loginbox input{width:100%;padding:9px 11px;border-radius:8px;border:1px solid #2b3440;background:#0b0f14;color:#e6edf3;font:inherit}\n.loginbox input:focus{outline:none;border-color:#1f6feb}\n.err{color:#ff9b9b;font-size:12px;min-height:18px;margin-top:8px}\ncode{background:#0b0f14;border:1px solid #1e2530;border-radius:4px;padding:1px 5px;font-size:12px}\n.hidden{display:none!important}\n.c{text-align:center}\nbutton.mini{font-size:12px;padding:2px 9px;border-radius:6px;border-color:#2b3440}\nbutton.mini:hover{background:#1d2530;border-color:#3a4553}\n.tag.multi{color:#ffd479;border-color:#5c4615;background:#231c0d}\n.tag.single{color:#9fb0c1;border-color:#2b3440}\ntr.detail-row>td{background:#0f141a;padding:10px 14px 14px 28px;border-bottom:1px solid #1e2530}\n.sub-table{width:auto;min-width:300px;font-size:13px;margin-top:4px}\n.sub-table td{padding:4px 16px 4px 0;border-bottom:1px solid #1a2028}\n.detail-hint{font-size:12px;color:#6d7d8e;margin-top:6px}\n.err-inline{color:#ff9b9b;font-size:12px}\npre.rawjson{background:#0b0f14;border:1px solid #1e2530;border-radius:8px;padding:10px;font-size:11px;line-height:1.45;max-height:240px;overflow:auto;color:#a9bccf;margin:8px 0 0;white-space:pre-wrap;word-break:break-all}\n\n/* ---------- 动效：只用 transform / opacity / grid-template-rows，单段 ≤300ms ---------- */\n@keyframes fade-up{from{opacity:0;transform:translate3d(0,8px,0)}to{opacity:1;transform:none}}\n@keyframes fade-in{from{opacity:0}to{opacity:1}}\n@keyframes shimmer{from{background-position:-140% 0}to{background-position:240% 0}}\n\n.reveal{animation:fade-up .26s cubic-bezier(.22,.61,.36,1) both}\n.reveal-1{animation-delay:.02s}\n.reveal-2{animation-delay:.06s}\n.reveal-3{animation-delay:.1s}\n.reveal-4{animation-delay:.14s}\n\n/* 表格行淡入：只在首屏渲染时加，后续刷新不重播，避免每次轮询闪一下 */\n/* 不写 fill:both —— 动画结束后不再保留合成层，避免把 sticky 表头压到下面去 */\ntr.row-in{animation:fade-in .22s ease}\n\n/* 只过渡颜色，不过渡尺寸，避免鼠标悬停时抖动 */\nbutton,input{transition:background-color .16s ease,border-color .16s ease,color .16s ease,opacity .16s ease}\nbutton:active:not([disabled]){transform:translateY(1px)}\nbutton:focus-visible,input:focus-visible{outline:2px solid #1f6feb;outline-offset:2px}\n.pill{transition:color .2s ease,border-color .2s ease,background-color .2s ease}\n\n.banner{animation:fade-up .22s cubic-bezier(.22,.61,.36,1) both}\n.login{animation:fade-in .18s ease both}\n.loginbox{animation:fade-up .24s cubic-bezier(.22,.61,.36,1) both}\n\n/* 明细展开：grid-template-rows 0fr→1fr，高度随内容自适应且不触发重排抖动 */\n.detail-wrap{display:grid;grid-template-rows:0fr;opacity:0;transition:grid-template-rows .28s cubic-bezier(.22,.61,.36,1),opacity .18s ease}\n.detail-wrap.open{grid-template-rows:1fr;opacity:1}\n.detail-inner{overflow:hidden;min-height:0}\n\n.skeleton{height:12px;border-radius:4px;background:linear-gradient(90deg,#182028 25%,#202a37 37%,#182028 63%);background-size:240% 100%;animation:shimmer 1.15s linear infinite}\n.skeleton+.skeleton{margin-top:8px}\n\n@media (prefers-reduced-motion:reduce){\n  *,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}\n}\n\n</head>\n<body>\n\n/* ---------- 视觉：深色层次 ---------- */\nbody{background-image:radial-gradient(900px 420px at 10% -10%,rgba(31,111,235,.10),transparent 62%),radial-gradient(700px 380px at 100% 0%,rgba(30,180,166,.06),transparent 55%)}\n.card{background:linear-gradient(180deg,#141a22,#10151c);box-shadow:inset 0 1px 0 rgba(255,255,255,.035);transition:border-color .18s ease,transform .18s ease,box-shadow .18s ease}\n.card:hover{border-color:#2b3644;transform:translateY(-1px);box-shadow:inset 0 1px 0 rgba(255,255,255,.05),0 6px 20px rgba(0,0,0,.28)}\nbutton.primary{box-shadow:0 2px 12px rgba(31,111,235,.32)}\nbutton.primary:hover{box-shadow:0 3px 16px rgba(31,111,235,.42)}\n.panel h2{display:flex;align-items:center;gap:8px}\n.panel h2:before{content:'';width:3px;height:13px;border-radius:2px;background:linear-gradient(180deg,#3d8bff,#1f6feb)}\ntr.snap-row{transition:box-shadow .15s ease}\ntr.snap-row:hover{box-shadow:inset 2px 0 0 #1f6feb}\n.tag.multi{background:linear-gradient(180deg,#2a2410,#231c0d)}\n\n/* ---------- 次级科目明细 ---------- */\n.detail-head{display:flex;align-items:center;gap:12px;font-size:12px;color:#8b9aab;margin:2px 0 10px}\n.detail-head .src{color:#7d8c9c;border:1px solid #2b3440;border-radius:999px;padding:1px 8px;font-size:11px}\n.detail-head .sum{margin-left:auto;color:#c9d6e3;font-variant-numeric:tabular-nums}\ntable.sub-table{width:100%;max-width:560px;border-collapse:collapse;font-size:13px}\ntable.sub-table td{padding:6px 10px 6px 0;border-bottom:1px solid #171f28;vertical-align:middle}\ntable.sub-table tr:last-child td{border-bottom:0}\ntable.sub-table td.subj{width:76px;color:#c9d6e3}\ntable.sub-table td.barcell{width:44%}\n.bar{height:6px;border-radius:999px;background:#1a222c;overflow:hidden}\n.bar>i{display:block;height:100%;border-radius:999px;background:#3d8bff;transform-origin:left center;animation:bar-in .38s cubic-bezier(.22,.61,.36,1)}\n@keyframes bar-in{from{transform:scaleX(0)}to{transform:scaleX(1)}}\n.bar.great>i{background:linear-gradient(90deg,#38c172,#7ee0a1)}\n.bar.good>i{background:linear-gradient(90deg,#2b7ff5,#66b3ff)}\n.bar.ok>i{background:linear-gradient(90deg,#c98a1a,#ffd479)}\n.bar.low>i{background:linear-gradient(90deg,#c1453f,#ff9b9b)}\n.score.great{color:#7ee0a1}\n.score.good{color:#8ad3ff}\n.score.ok{color:#ffd479}\n.score.low{color:#ff9b9b}\n\n/* ---------- 数据可视化：环形 / 雷达 / 参考线 ---------- */\n.detail-head{display:flex;align-items:center;gap:14px;font-size:12px;color:#8b9aab;margin:2px 0 14px}\n.dh-text{line-height:1.35}\n.dh-title{color:#c9d6e3;font-size:13px;font-weight:600}\n.dh-sub{color:#7d8c9c;font-variant-numeric:tabular-nums}\n.detail-head .src{margin-left:auto;color:#7d8c9c;border:1px solid #2b3440;border-radius:999px;padding:1px 8px;font-size:11px}\n.donut{flex:0 0 auto}\n.donut .track{stroke:#1a222c}\n.donut .prog{stroke:#3d8bff;stroke-linecap:round;transform:rotate(-90deg);transform-origin:50% 50%;animation:donut-draw .55s cubic-bezier(.22,.61,.36,1) both}\n.donut .pct{fill:#e6edf3;font-size:13px;font-weight:650;text-anchor:middle;dominant-baseline:central}\n@keyframes donut-draw{from{stroke-dashoffset:var(--from)}to{stroke-dashoffset:0}}\n\n.detail-grid{display:grid;grid-template-columns:248px minmax(260px,560px);gap:24px;align-items:start}\n.viz{display:flex;justify-content:center}\n.radar{display:block;overflow:visible}\n.radar .grid-line{stroke:#1e2833;fill:none}\n.radar .axis{stroke:#1a222c}\n.radar .lbl{fill:#7d8c9c;font-size:11px}\n.radar .val{fill:#8b9aab;font-size:9px;text-anchor:middle}\n.radar-poly{fill:rgba(61,139,255,.16);stroke:#3d8bff;stroke-width:1.6;stroke-linejoin:round;transform-box:fill-box;transform-origin:center;animation:radar-in .5s cubic-bezier(.22,.61,.36,1) both}\n.radar-dot{fill:#0d1014;stroke:#3d8bff;stroke-width:1.6;animation:fade-in .4s ease .18s both}\n@keyframes radar-in{from{transform:scale(.55);opacity:0}to{transform:scale(1);opacity:1}}\n@media (max-width:760px){.detail-grid{grid-template-columns:1fr}.viz{justify-content:flex-start}}\n\n.bars{display:flex;flex-direction:column;gap:8px}\n.sub-row{display:grid;grid-template-columns:64px 96px 1fr;gap:12px;align-items:center;transition:opacity .15s ease}\n.sub-row:hover .bar>i{filter:brightness(1.18)}\n.sub-row .subj{color:#c9d6e3;font-size:13px}\n.sub-row .val{text-align:right;font-variant-numeric:tabular-nums;font-size:13px}\n.bar{position:relative}\n.bar:after{content:'';position:absolute;left:70%;top:-3px;bottom:-3px;width:1px;background:rgba(255,255,255,.15)}\n.bars-foot{margin-top:10px;font-size:11px;color:#5f6f80}\n\n/* ---------- 版面：更宽、更大、无内嵌滚动 ---------- */\n.wrap{max-width:1440px;padding:22px 28px 76px}\nheader{padding:8px 0 20px;margin-bottom:22px}\n.brand{font-size:19px;letter-spacing:.4px}\n.tablewrap{max-height:none;overflow:visible}\n.panel{padding:20px 22px;border-radius:15px;margin-bottom:20px}\n.panel h2{font-size:15px;margin:0 0 16px}\ntable{font-size:13.5px}\ntd{padding:11px 12px}\n\n/* ---------- 英雄区：最近一次考试 ---------- */\n.hero{display:grid;grid-template-columns:1fr auto auto;align-items:center;gap:30px;padding:26px 30px;margin-bottom:20px;border-radius:16px;border:1px solid #1e2836;background:linear-gradient(120deg,#121a24,#0f1620 46%,#101a23);position:relative;overflow:hidden}\n.hero:before{content:'';position:absolute;right:-8%;top:-45%;width:560px;height:340px;background:radial-gradient(closest-side,rgba(56,140,255,.20),transparent);pointer-events:none;animation:hero-glow 14s ease-in-out infinite alternate}\n@keyframes hero-glow{from{transform:translate3d(0,0,0) scale(1);opacity:.72}to{transform:translate3d(-38px,16px,0) scale(1.12);opacity:1}}\n.hero-kicker{font-size:11px;letter-spacing:.2em;color:#5f7d9c}\n.hero-title{font-size:27px;line-height:1.25;margin:7px 0 9px;font-weight:650;letter-spacing:.2px}\n.hero-meta{font-size:12.5px;color:#7d8c9c}\n.hero-score{font-size:54px;font-weight:680;font-variant-numeric:tabular-nums;line-height:1;text-align:right;letter-spacing:-.02em}\n.hero-score small{font-size:15px;color:#6d7d8e;font-weight:500;margin-left:6px;letter-spacing:0}\n.hero-ring{width:112px;height:112px}\n.hero-ring .track{stroke:#1a2430}\n.hero-ring .prog{stroke:#54a6ff;stroke-linecap:round;transform:rotate(-90deg);transform-origin:50% 50%;animation:donut-draw .7s cubic-bezier(.22,.61,.36,1) both}\n.hero-ring text{fill:#e6edf3;font-size:22px;font-weight:680;text-anchor:middle;dominant-baseline:central}\n.hero-ring .cap{font-size:9px;fill:#5f7d9c;font-weight:500;letter-spacing:.12em}\n\n/* ---------- 指标条 ---------- */\n.cards{grid-template-columns:repeat(4,1fr);gap:14px}\n.card{padding:16px 18px;border-radius:13px}\n.card .v{font-size:26px}\n\n/* ---------- 行内得分率 ---------- */\n.score-cell{display:flex;flex-direction:column;align-items:flex-end}\n.rail{position:relative;height:5px;width:112px;border-radius:999px;background:#161f29;overflow:hidden;margin-top:7px}\n.rail>i{display:block;height:100%;border-radius:999px;background:linear-gradient(90deg,#2b7ff5,#66b3ff);transform-origin:left center;animation:rail-grow .55s cubic-bezier(.22,.61,.36,1)}\n@keyframes rail-grow{from{transform:scaleX(0)}to{transform:scaleX(1)}}\n.rail.great>i{background:linear-gradient(90deg,#2f9e63,#7ee0a1)}\n.rail.good>i{background:linear-gradient(90deg,#2b7ff5,#66b3ff)}\n.rail.ok>i{background:linear-gradient(90deg,#b8791a,#ffd479)}\n.rail.low>i{background:linear-gradient(90deg,#a83c36,#ff9b9b)}\n\n/* ---------- 明细：两列铺开，一屏装下 ---------- */\n.detail-grid{grid-template-columns:288px 1fr;gap:28px}\n.subj-grid{display:grid;grid-template-columns:repeat(2,minmax(300px,1fr));gap:0 32px}\n.srow{display:grid;grid-template-columns:66px 92px 1fr;align-items:center;gap:12px;padding:6px 0;border-bottom:1px solid #151d26}\n.srow:hover .bar>i{filter:brightness(1.2)}\n.srow .subj{color:#c9d6e3;font-size:13px}\n.srow .val{text-align:right;font-variant-numeric:tabular-nums;font-size:13px}\n@media (max-width:1180px){.subj-grid{grid-template-columns:1fr}.cards{grid-template-columns:repeat(2,1fr)}}\n@media (max-width:820px){.hero{grid-template-columns:1fr;gap:16px}.hero-score{text-align:left}.detail-grid{grid-template-columns:1fr}}\n\n/* ---------- 大胆版：极光 / 玻璃 / 辉光 ---------- */\nbody{background-attachment:fixed}\nbody:before{content:'';position:fixed;left:-10%;right:-10%;top:-18%;height:72vh;z-index:-1;pointer-events:none;\n  background:radial-gradient(46% 56% at 16% 10%,rgba(52,120,255,.22),transparent 70%),\n             radial-gradient(42% 50% at 84% 4%,rgba(0,222,200,.15),transparent 72%),\n             radial-gradient(40% 46% at 54% -8%,rgba(150,90,255,.18),transparent 70%);\n  filter:blur(12px);animation:aurora 22s ease-in-out infinite alternate}\n@keyframes aurora{0%{transform:translate3d(-1.5%,0,0) scale(1)}100%{transform:translate3d(2%,2.5%,0) scale(1.14)}}\n\n.panel{background:linear-gradient(165deg,rgba(21,29,39,.92),rgba(13,19,26,.95));border:1px solid rgba(120,170,255,.10);\n  box-shadow:0 14px 40px rgba(0,0,0,.38),inset 0 1px 0 rgba(255,255,255,.045)}\n.card{background:linear-gradient(165deg,rgba(23,32,43,.95),rgba(14,20,27,.96));border:1px solid rgba(120,170,255,.10);\n  box-shadow:0 10px 28px rgba(0,0,0,.32),inset 0 1px 0 rgba(255,255,255,.05)}\n.card:hover{transform:translateY(-2px);border-color:rgba(120,170,255,.28);box-shadow:0 18px 42px rgba(0,0,0,.46),0 0 0 1px rgba(90,150,255,.16)}\n\n.hero{border:1px solid transparent;\n  background-image:linear-gradient(120deg,#111a24,#0d151d 48%,#101b22),\n                   linear-gradient(120deg,rgba(61,139,255,.8),rgba(29,224,200,.55) 45%,rgba(150,90,255,.65));\n  background-origin:border-box;background-clip:padding-box,border-box;\n  box-shadow:0 26px 64px rgba(0,0,0,.5)}\n.hero-title{background:linear-gradient(92deg,#ffffff,#a9d2ff 58%,#8fe7dd);-webkit-background-clip:text;background-clip:text;color:transparent}\n.hero-score{text-shadow:0 0 30px rgba(84,166,255,.35)}\n.hero-ring .prog{filter:drop-shadow(0 0 10px rgba(84,166,255,.7))}\n\n.rail>i{box-shadow:0 0 12px rgba(84,166,255,.45)}\n.rail.great>i{box-shadow:0 0 12px rgba(126,224,161,.45)}\n.rail.ok>i{box-shadow:0 0 12px rgba(255,212,121,.42)}\n.rail.low>i{box-shadow:0 0 12px rgba(255,155,155,.42)}\n.radar-poly{filter:drop-shadow(0 0 14px rgba(61,139,255,.6))}\n.dh-title{font-size:14px;background:linear-gradient(92deg,#fff,#9fd0ff);-webkit-background-clip:text;background-clip:text;color:transparent}\n.srow{grid-template-columns:26px 66px 92px 1fr;padding:7px 0;border-bottom:1px solid #141c25;transition:background-color .16s ease}\n.srow:hover{background:linear-gradient(90deg,rgba(61,139,255,.09),transparent)}\n.srow .rank{width:20px;height:20px;border-radius:6px;display:inline-flex;align-items:center;justify-content:center;\n  font-size:10.5px;color:#8fb6ff;background:rgba(61,139,255,.13);border:1px solid rgba(61,139,255,.28)}\n.srow:nth-child(-n+6) .rank{color:#0d1014;background:linear-gradient(135deg,#8fd7ff,#5aa8ff);border-color:transparent}\ntr.snap-row{transition:background-color .16s ease}\ntr.snap-row:hover{background:linear-gradient(90deg,rgba(61,139,255,.09),transparent)}\n.panel h2:before{background:linear-gradient(180deg,#5ad7ff,#3d8bff);box-shadow:0 0 10px rgba(90,180,255,.6)}\n\n/* ---------- 试卷信息 ---------- */\n.paper{border:1px solid rgba(120,170,255,.12);border-radius:12px;padding:14px 16px;margin:0 0 16px;background:linear-gradient(160deg,rgba(20,28,38,.85),rgba(13,19,26,.9))}\n.paper-h{font-size:12px;letter-spacing:.12em;color:#5f7d9c;margin-bottom:10px}\n.paper-grid{display:flex;flex-wrap:wrap;gap:8px}\n.pchip{display:inline-flex;align-items:baseline;gap:7px;padding:5px 11px;border-radius:9px;background:rgba(61,139,255,.07);border:1px solid rgba(61,139,255,.16)}\n.pchip .pk{font-size:11px;color:#7d8c9c}\n.pchip .pv{font-size:13px;color:#dbe7f3;font-variant-numeric:tabular-nums}\n.paper-comment{margin-top:11px;font-size:12.5px;color:#9fb3c6;padding-left:11px;border-left:2px solid rgba(61,139,255,.45)}\n\n.paper-raw{font-size:12px;color:#7d8c9c;margin:0 0 14px}\n.paper-raw summary{cursor:pointer;color:#8fb6ff}\n\n.donut{flex:0 0 auto}\n.donut .pct{font-size:16px;font-weight:700;fill:#e9f2fb}\n.donut .cap{font-size:9px;fill:#6d7d8e;letter-spacing:.04em}\n\n/* ================= 扁平化重制（覆盖前面的拟物/玻璃/辉光） ================= */\nbody{background:#0b0d10;background-image:none}\nbody:before{display:none}\n.wrap{max-width:1520px}\n.panel,.card,.hero{background:#11151a;border:1px solid #232a33;border-radius:3px;box-shadow:none;backdrop-filter:none}\n.hero{background:#11151a;border:1px solid #232a33;border-left:3px solid #2f81f7;box-shadow:none}\n.hero:before{display:none}\n.hero-title{background:none;-webkit-background-clip:border-box;background-clip:border-box;color:#f0f4f8;-webkit-text-fill-color:#f0f4f8;font-weight:750;letter-spacing:-.01em}\n.hero-score{text-shadow:none;font-weight:800}\n.hero-kicker{color:#5b6673}\nbutton{border-radius:2px;background:#151a21;border:1px solid #2b333d;color:#d5dde6}\nbutton:hover{background:#1c232b;border-color:#3b4654}\nbutton.primary{background:#2f81f7;border-color:#2f81f7;color:#fff;box-shadow:none}\nbutton.primary:hover{background:#4c9bff;box-shadow:none}\n.card{border-radius:3px}\n.card:hover{transform:none;background:#151a21;border-color:#3b4654;box-shadow:none}\n.card .v{font-weight:800}\n.panel h2{font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:#8b97a5;padding-bottom:11px;border-bottom:1px solid #232a33;margin-bottom:16px;position:relative}\n.panel h2:before{display:none}\n.panel h2:after{content:'';position:absolute;left:0;bottom:-1px;height:2px;width:100%;background:#2f81f7;transform-origin:left center;animation:line-grow .55s cubic-bezier(.2,.75,.2,1) both}\n@keyframes line-grow{from{transform:scaleX(0)}to{transform:scaleX(1)}}\n.pill,.tag,.pchip,.src,.rank,.mini,.paper,.paper-raw,pre.rawjson,.sub-table td,.bars,.bar,.rail{border-radius:2px}\n.tag.multi{background:#1a2635;border-color:#2f4a6b;color:#8fc3ff}\n.tag.single{background:#151a21;border-color:#2b333d;color:#98a4b2}\ntr.snap-row:hover{background:#151a21;box-shadow:none}\ntr.snap-row:hover td:first-child{box-shadow:inset 2px 0 0 #2f81f7}\n.rail>i,.hero-ring .prog,.donut .prog,.radar-poly{filter:none}\n.rail,.bar{background:#1a2028}\n.donut .track,.hero-ring .track{stroke:#1a2028}\n.score{color:#eef4fa}\n.score.great{color:#2ec27e}.score.good{color:#4c9bff}.score.ok{color:#e3b341}.score.low{color:#f85149}\n.rail.great>i{background:#2ec27e}.rail.good>i{background:#4c9bff}.rail.ok>i{background:#e3b341}.rail.low>i{background:#f85149}\n.radar-poly{fill:rgba(47,129,247,.14);stroke:#2f81f7}\n.radar-dot{stroke:#2f81f7;fill:#0b0d10}\n.pchip{border-color:#2b333d;background:#151a21}\n.paper{background:#0e1216;border-color:#232a33}\n.paper-comment{border-left-color:#2f81f7;color:#9aa7b4}\n.rank{color:#8fa3b8;background:#151a21;border-color:#2b333d}\n.srow:nth-child(-n+6) .rank{color:#fff;background:#2f81f7;border-color:#2f81f7}\n.detail-wrap{transition:grid-template-rows .34s cubic-bezier(.2,.75,.2,1),opacity .22s ease}\ntr.detail-row>td{animation:sheet-in .3s cubic-bezier(.2,.75,.2,1) both}\n@keyframes sheet-in{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:none}}\n.loginbox{background:#11151a;border-color:#232a33;border-radius:3px}\ninput{border-radius:2px}\n.detail-head .src{border-color:#2b333d;color:#8b97a5}\n\n/* ---------- 答题卡缩略图 ---------- */\n.shots-h{font-size:12px;letter-spacing:.1em;color:#5b6673;margin:14px 0 8px}\n.shots{display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:10px;margin-bottom:16px}\n.shot{position:relative;display:block;border:1px solid #232a33;background:#0e1216;overflow:hidden;text-decoration:none}\n.shot img{display:block;width:100%;height:96px;object-fit:cover;opacity:.92;transition:transform .3s cubic-bezier(.2,.75,.2,1),opacity .2s}\n.shot:hover img{transform:scale(1.04);opacity:1}\n.shot-i{position:absolute;left:6px;top:6px;font-size:10px;padding:1px 5px;background:#2f81f7;color:#fff}\n\n.shots-imp{margin:14px 0 16px}\n.imp-ta{width:100%;max-width:720px;height:64px;background:#0e1216;border:1px solid #232a33;color:#cfd8e3;font:12px/1.5 ui-monospace,monospace;padding:8px;border-radius:2px;resize:vertical}\n.imp-btn{margin-top:8px;margin-right:10px}\n.imp-msg{font-size:12px;color:#8b97a5}\n\n.shots-grp{margin-bottom:18px}\n.shots-grp .shots-h{margin:0 0 8px}\n.shots-grp .shots{margin-bottom:0}\n\n.shot--mark{border-color:#5a2a2a}\n.shot--mark .shot-i{background:#f85149}\n\n/* ---------- 答题卡灯箱（合成版） ---------- */\n.shot-mark{position:absolute;right:6px;top:6px;font-size:10px;padding:1px 5px;background:#f85149;color:#fff}\n.lightbox{position:fixed;inset:0;z-index:60;display:none;background:rgba(4,6,9,.94)}\n.lightbox.open{display:block}\n.lb-inner{position:absolute;inset:0;display:flex;flex-direction:column;padding:0}\n.lb-close{position:absolute;right:18px;top:14px;z-index:2;width:36px;height:36px;font-size:22px;line-height:1;background:#151a21;border:1px solid #2b333d;color:#d5dde6;border-radius:2px;cursor:pointer}\n.lb-title{flex:0 0 auto;padding:14px 20px;font-size:12px;letter-spacing:.1em;color:#8b97a5;border-bottom:1px solid #232a33}\n.lb-stage{position:relative;flex:1 1 auto;display:flex;align-items:center;justify-content:center;overflow:auto;padding:18px}\n.lb-stage img{max-width:100%;max-height:calc(100vh - 120px);display:block}\n.lb-frame{position:relative;display:inline-block;line-height:0}\n.lb-base{position:relative;z-index:1;display:block;max-width:100%;max-height:calc(100vh - 120px)}\n.lb-over{position:absolute;left:0;top:0;width:100%;height:100%;z-index:2;pointer-events:none;object-fit:fill}\n\n.lb-mark{position:absolute;z-index:3;border:2px solid #f85149;background:rgba(248,81,73,.10);box-sizing:border-box}\n.lb-mark i{position:absolute;right:-1px;top:-18px;font-style:normal;font-size:11px;line-height:16px;padding:0 4px;background:#f85149;color:#fff;white-space:nowrap}\n.lb-note{padding:0 20px 16px;font-size:12px;color:#8b97a5}\n\n.shot--lost{border-color:#f85149}\n.shot--lost .shot-i{background:#f85149}\n</style>\n<div class=\"wrap\">\n  <header class=\"reveal reveal-1\">\n    <div class=\"brand\">慧学星 · 成绩单监控</div>\n    <div class=\"spacer\"></div>\n    <span id=\"pill\" class=\"pill\">加载中</span>\n    <button id=\"btnRefresh\" class=\"ghost\">刷新</button>\n    <button id=\"btnPoll\" class=\"primary\">立即检查</button>\n    <button id=\"btnRelogin\" class=\"ghost\">重新登录上游</button>\n    <button id=\"btnDiag\" class=\"ghost\">诊断</button>\n    <button id=\"btnLogout\" class=\"ghost danger\">退出</button>\n  </header>\n\n  <div id=\"banner\" class=\"banner hidden\"></div>\n\n  <section class=\"hero reveal reveal-2\">\n    <div>\n      <div class=\"hero-kicker\">LATEST EXAM</div>\n      <h1 class=\"hero-title\" id=\"heroTitle\">—</h1>\n      <div class=\"hero-meta\" id=\"heroMeta\">—</div>\n    </div>\n    <div class=\"hero-score\"><span id=\"heroScore\">—</span><small id=\"heroFull\"></small></div>\n    <div class=\"hero-ring\" id=\"heroRing\"></div>\n  </section>\n\n  <section class=\"cards reveal reveal-3\">\n    <div class=\"card\"><div class=\"k\">已记录考试</div><div class=\"v\" id=\"cSnap\">-</div><div class=\"s\">最近一次抓取到的全部成绩单</div></div>\n    <div class=\"card\"><div class=\"k\">近 24h 变化</div><div class=\"v\" id=\"cEvents\">-</div><div class=\"s\">新发布 + 分数变化</div></div>\n    <div class=\"card\"><div class=\"k\">观察到的检查间隔</div><div class=\"v\" id=\"cInterval\">-</div><div class=\"s\">由最近运行记录推算（分钟）</div></div>\n    <div class=\"card\"><div class=\"k\">上游会话</div><div class=\"v small\" id=\"cSession\">-</div><div class=\"s\" id=\"cSessionNote\">-</div></div>\n  </section>\n\n  <section class=\"panel reveal reveal-4\">\n    <h2>最新成绩单</h2>\n    <div class=\"tablewrap\">\n      <table>\n        <thead><tr><th>考试</th><th class=\"c\">类型</th><th class=\"num\">分数</th><th>考试日期</th><th>最近变化</th><th class=\"c\">明细</th></tr></thead>\n        <tbody id=\"tbSnap\"></tbody>\n      </table>\n    </div>\n    <div class=\"detail-hint\">「多科」行点 <b>明细</b> 展开各科分数；单科行只有一科，右侧显示 —</div>\n    <div class=\"empty hidden\" id=\"snapEmpty\">还没有数据。定时任务第一次运行后会写入基线。</div>\n  </section>\n\n  <section class=\"panel reveal reveal-4\">\n    <h2>发布 / 变化记录</h2>\n    <div class=\"tablewrap\">\n      <table>\n        <thead><tr><th>时间</th><th>类型</th><th>考试</th><th>分数变化</th></tr></thead>\n        <tbody id=\"tbEvents\"></tbody>\n      </table>\n    </div>\n    <div class=\"empty hidden\" id=\"eventsEmpty\">暂无事件。首次运行只建立基线，之后的发布与变化才会记录。</div>\n  </section>\n\n  <section class=\"panel reveal reveal-5\">\n    <h2>运行日志（最近 20 次）</h2>\n    <div class=\"tablewrap\">\n      <table>\n        <thead><tr><th>开始时间</th><th>状态</th><th class=\"num\">耗时</th><th class=\"num\">条目</th><th class=\"num\">事件</th><th>说明</th></tr></thead>\n        <tbody id=\"tbRuns\"></tbody>\n      </table>\n    </div>\n  </section>\n\n  <section class=\"panel hidden\" id=\"diagPanel\">\n    <h2>诊断（会真实登录一次上游，不覆盖已存会话）</h2>\n    <pre id=\"diagOut\" class=\"diag\">-</pre>\n  </section>\n\n  <footer>时间按 Asia/Shanghai 显示，数据库内以 UTC 存储。考试名称/日期由字段候选规则解析，若显示不对请点「诊断」把 examList 样例发我。</footer>\n\n  <div id=\"login\" class=\"login hidden\">\n    <div class=\"loginbox\">\n      <h1>需要密码</h1>\n      <p class=\"muted\">此界面受密码保护。密码由部署者用 <code>wrangler secret put ADMIN_PASSWORD</code> 设置。</p>\n      <input id=\"pw\" type=\"password\" placeholder=\"管理密码\" autocomplete=\"current-password\" />\n      <button id=\"btnLogin\" class=\"primary full\">进入</button>\n      <div id=\"loginErr\" class=\"err\"></div>\n    </div>\n  </div>\n</div>\n<script>\n(function () {\n  var state = null;\n  var firstRender = true;\n  var LABEL = { new_report: '新成绩单发布', score_change: '分数变化', score_filled: '出分', score_cleared: '分数清空' };\n\n  function el(id) { return document.getElementById(id); }\n  function esc(s) {\n    if (s === null || s === undefined) return '';\n    return String(s).replace(/[&<>\"']/g, function (c) {\n      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c];\n    });\n  }\n  function dt(iso) {\n    if (!iso) return '-';\n    var d = new Date(iso);\n    if (isNaN(d.getTime())) return esc(iso);\n    var parts = new Intl.DateTimeFormat('zh-CN', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false }).formatToParts(d);\n    var m = {};\n    parts.forEach(function (p) { m[p.type] = p.value; });\n    return m.year + '/' + m.month + '/' + m.day + ' ' + m.hour + ':' + m.minute + ':' + m.second;\n  }\n  function api(path, opts) {\n    var init = Object.assign({ credentials: 'same-origin' }, opts || {});\n    if (init.body) { init.headers = { 'content-type': 'application/json' }; }\n    return fetch(path, init).then(function (r) {\n      return r.text().then(function (t) {\n        var j;\n        try { j = JSON.parse(t); } catch (e) { j = { ok: false, error: 'bad_response', raw: t.slice(0, 300) }; }\n        return { status: r.status, body: j };\n      });\n    });\n  }\n  function showLogin(msg) { el('login').classList.remove('hidden'); el('loginErr').textContent = msg || ''; el('pw').focus(); }\n  function hideLogin() { el('login').classList.add('hidden'); el('loginErr').textContent = ''; }\n  function banner(text, warn) {\n    var b = el('banner');\n    if (!text) { b.classList.add('hidden'); return; }\n    b.textContent = text;\n    b.style.background = warn ? '#241313' : '#231c0d';\n    b.style.borderColor = warn ? '#6a2b2b' : '#5c4615';\n    b.style.color = warn ? '#ff9b9b' : '#ffd479';\n    b.classList.remove('hidden');\n  }\n  function busy(btn, on, text) {\n    if (!btn) return;\n    btn.disabled = on;\n    if (on) { btn.dataset.label = btn.textContent; btn.textContent = text; }\n    else if (btn.dataset.label) { btn.textContent = btn.dataset.label; }\n  }\n\n  function heroRingSvg(ratio) {\n    if (ratio === null || ratio === undefined) return '';\n    var C = 2 * Math.PI * 44;\n    var len = C * ratio;\n    return '<svg viewBox=\"0 0 112 112\" width=\"112\" height=\"112\" role=\"img\" aria-label=\"得分率 ' + Math.round(ratio * 100) + '%\">'\n      + '<circle class=\"track\" cx=\"56\" cy=\"56\" r=\"44\" fill=\"none\" stroke-width=\"7\"/>'\n      + '<circle class=\"prog\" cx=\"56\" cy=\"56\" r=\"44\" fill=\"none\" stroke-width=\"7\" stroke-dasharray=\"' + len.toFixed(1) + ' ' + C.toFixed(1) + '\" style=\"--from:' + len.toFixed(1) + '\"/>'\n      + '<text x=\"56\" y=\"52\">' + Math.round(ratio * 100) + '</text>'\n      + '<text class=\"cap\" x=\"56\" y=\"70\">得分率</text></svg>';\n  }\n\n  function railCls(ratio) {\n    if (ratio === null || ratio === undefined) return '';\n    return ratio >= 0.85 ? 'great' : ratio >= 0.7 ? 'good' : ratio >= 0.5 ? 'ok' : 'low';\n  }\n\n  function render(s) {\n    state = s;\n\n    // 英雄区：取考试日期最新的那条\n    var hero = (s.snapshots || []).slice().sort(function (a, b) {\n      var da = a.exam_date || '';\n      var db = b.exam_date || '';\n      if (da === db) return 0;\n      return da < db ? 1 : -1;\n    })[0];\n    if (hero) {\n      el('heroTitle').textContent = hero.title || ('#' + hero.exam_id);\n      el('heroMeta').textContent = (hero.exam_date || '日期未知') + ' · ' + (hero.is_multi ? '多科' : '单科')\n        + (hero.full ? ' · 满分 ' + hero.full : '') + (hero.last_change_at ? ' · 最近变化 ' + dt(hero.last_change_at) : '');\n      el('heroScore').textContent = hero.score_text === null || hero.score_text === undefined ? '—' : hero.score_text;\n      el('heroFull').textContent = hero.full ? ' / ' + hero.full : '';\n      el('heroRing').innerHTML = heroRingSvg(hero.ratio);\n    }\n    el('cSnap').textContent = s.snapshotCount;\n    el('cEvents').textContent = s.stats.last24h;\n    el('cInterval').textContent = s.stats.observedIntervalMinutes === null ? '-' : (s.stats.observedIntervalMinutes + ' 分');\n    el('cSession').textContent = s.session ? (s.session.loginOk ? '已登录' : '需重新登录') : '尚未登录';\n    el('cSessionNote').textContent = s.session ? ('上次登录 ' + dt(s.session.updatedAt)) : ('首次运行时会自动登录 ' + s.config.upstream);\n\n    var last = s.runs[0];\n    var pill = el('pill');\n    if (!last) { pill.textContent = '未运行'; pill.className = 'pill warn'; }\n    else if (last.status === 'ok' || last.status === 'changed' || last.status === 'baseline') { pill.textContent = '正常'; pill.className = 'pill ok'; }\n    else if (last.status === 'auth_failed') { pill.textContent = '登录失效'; pill.className = 'pill bad'; }\n    else { pill.textContent = last.status; pill.className = 'pill warn'; }\n\n    if (last) {\n      if (last.status === 'auth_failed') banner('上游登录失败：' + (last.message || '') + '　请先核对机密里的账号密码，再点\"重新登录上游\"。', true);\n      else if (last.status === 'baseline') banner('已完成首次基线（' + last.exams_seen + ' 份成绩单）。本次不产生事件，之后的新发布与分数变化才会记录。', false);\n      else if (last.status !== 'ok' && last.status !== 'changed') banner('上次检查异常（' + last.status + '）：' + (last.message || ''), true);\n      else banner('', false);\n    }\n\n    el('tbSnap').innerHTML = (s.snapshots || []).map(function (r) {\n      var cls = railCls(r.ratio);\n      var score = (r.score_text === null || r.score_text === undefined)\n        ? '<span class=\"null\">未出分/缺考</span>'\n        : '<span class=\"score ' + cls + '\">' + esc(r.score_text) + '</span>' + (r.full ? '<span class=\"null\"> /' + esc(String(r.full)) + '</span>' : '');\n      var rail = (r.ratio === null || r.ratio === undefined) ? '' : '<div class=\"rail ' + cls + '\"><i style=\"width:' + (r.ratio * 100).toFixed(1) + '%\"></i></div>';\n      var type = r.is_multi ? '<span class=\"tag multi\">多科</span>' : '<span class=\"tag single\">单科</span>';\n      var act = '<button class=\"mini\" data-exam=\"' + esc(r.exam_id) + '\" data-type=\"' + esc(r.exam_type_id || '') + '\">' + (r.is_multi ? '明细' : '详情') + '</button>';\n      return '<tr class=\"snap-row\">'\n        + '<td>' + esc(r.title || ('#' + r.exam_id)) + '</td>'\n        + '<td class=\"c\">' + type + '</td>'\n        + '<td class=\"num score-cell\">' + score + rail + '</td>'\n        + '<td>' + (r.exam_date ? esc(r.exam_date) : '-') + '</td>'\n        + '<td>' + (r.last_change_at ? dt(r.last_change_at) : '-') + '</td>'\n        + '<td class=\"c\">' + act + '</td></tr>';\n    }).join('');\n    el('snapEmpty').classList.toggle('hidden', (s.snapshots || []).length > 0);\n    if (firstRender) {\n      Array.prototype.forEach.call(el('tbSnap').children, function (tr, i) {\n        tr.classList.add('row-in');\n        tr.style.animationDelay = Math.min(i * 18, 150) + 'ms';\n      });\n    }\n\n    el('tbEvents').innerHTML = (s.events || []).map(function (e) {\n      var change = (e.old_score === null || e.old_score === undefined ? '—' : esc(e.old_score)) + ' → ' + (e.new_score === null || e.new_score === undefined ? '—' : esc(e.new_score));\n      if (e.delta !== null && e.delta !== undefined) change += ' <span class=\"null\">(' + (e.delta > 0 ? '+' : '') + e.delta + ')</span>';\n      return '<tr><td>' + dt(e.detected_at) + '</td><td><span class=\"tag ' + esc(e.kind) + '\">' + esc(LABEL[e.kind] || e.kind) + '</span></td><td>' + esc(e.title || e.subject_name || ('#' + e.exam_id)) + '</td><td>' + change + '</td></tr>';\n    }).join('');\n    el('eventsEmpty').classList.toggle('hidden', (s.events || []).length > 0);\n\n    firstRender = false;\n    el('tbRuns').innerHTML = (s.runs || []).map(function (r) {\n      return '<tr><td>' + dt(r.started_at) + '</td><td>' + esc(r.status) + '</td><td class=\"num\">' + (r.duration_ms === null ? '-' : r.duration_ms + 'ms') + '</td><td class=\"num\">' + (r.exams_seen || 0) + '</td><td class=\"num\">' + (r.events_created || 0) + '</td><td>' + esc(r.message || '') + '</td></tr>';\n    }).join('');\n  }\n\n  function loadState() {\n    return api('/admin/api/state').then(function (r) {\n      if (r.status === 401) { showLogin('会话已过期，请重新输入密码。'); return; }\n      if (!r.body.ok) { showLogin('服务端未就绪：' + (r.body.message || r.body.error || '')); return; }\n      hideLogin();\n      render(r.body);\n    });\n  }\n  // ---------- 多科明细展开（二级菜单）----------\n  var detailCache = {};\n\n  var SUBJECT_ORDER = ['语文', '数学', '英语', '政治', '历史', '地理', '物理', '化学', '生物', '技术', '史地政', '理综', '文综'];\n  var SRC_LABEL = { examReportList: '明细接口', examCourse: '课程列表', 'alldetail-html': '报告页解析', db: '已入库' };\n\n  function round1(n) { return Math.round(n * 10) / 10; }\n\n  var STD_FULL = { 语文: 150, 数学: 150, 英语: 150, 物理: 100, 化学: 100, 生物: 100, 政治: 100, 历史: 100, 地理: 100, 技术: 100, 史地政: 300, 理综: 300, 文综: 300 };\n\n  function withRatio(rows) {\n    return rows.map(function (r) {\n      var isTotal = /总分|合计|总计/.test(String(r.subject || ''));\n      var score = r.score === null || r.score === undefined ? null : String(r.score);\n      var full = (r.full === null || r.full === undefined || r.full === '') ? (STD_FULL[r.subject] || (isTotal ? 1050 : null)) : Number(r.full);\n      var num = score === null ? NaN : parseFloat(score);\n      var ratio = full && isFinite(num) ? Math.max(0, Math.min(1, num / full)) : null;\n      return { subject: r.subject, score: score, full: full, ratio: ratio, isTotal: isTotal };\n    }).filter(function (x) { return !x.isTotal; });\n  }\n\n  function donutSvg(ratio, score, full) {\n    var R = 30;\n    var C = 2 * Math.PI * R;\n    var r2 = ratio === null || ratio === undefined ? 0 : ratio;\n    var len = C * r2;\n    var scoreTxt = score === null || score === undefined ? '—' : String(score);\n    return '<svg class=\"donut\" width=\"76\" height=\"76\" viewBox=\"0 0 76 76\" role=\"img\" aria-label=\"' + esc(scoreTxt) + ' / ' + esc(String(full)) + '\">'\n      + '<circle class=\"track\" cx=\"38\" cy=\"38\" r=\"' + R + '\" fill=\"none\" stroke-width=\"5\"/>'\n      + '<circle class=\"prog\" cx=\"38\" cy=\"38\" r=\"' + R + '\" fill=\"none\" stroke-width=\"5\"'\n      + ' stroke-dasharray=\"' + len.toFixed(1) + ' ' + C.toFixed(1) + '\" style=\"--from:' + len.toFixed(1) + '\"/>'\n      + '<text class=\"pct\" x=\"38\" y=\"35\">' + esc(scoreTxt) + '</text>'\n      + (full ? '<text class=\"cap\" x=\"38\" y=\"49\">/ ' + esc(String(full)) + '</text>' : '')\n      + '</svg>';\n  }\n\n  function radarSvg(items) {\n    var n = items.length;\n    if (n < 3) return '';\n    var C = 120;\n    var R = 82;\n    var parts = [];\n    [0.34, 0.67, 1].forEach(function (k) {\n      var p = [];\n      for (var i = 0; i < n; i++) {\n        var a = (-90 + (360 / n) * i) * Math.PI / 180;\n        p.push((C + Math.cos(a) * R * k).toFixed(1) + ',' + (C + Math.sin(a) * R * k).toFixed(1));\n      }\n      parts.push('<polygon class=\"grid-line\" points=\"' + p.join(' ') + '\" stroke-dasharray=\"3 4\"/>');\n    });\n    var poly = [];\n    var dots = [];\n    for (var i = 0; i < n; i++) {\n      var ang = (-90 + (360 / n) * i) * Math.PI / 180;\n      var x1 = C + Math.cos(ang) * R;\n      var y1 = C + Math.sin(ang) * R;\n      parts.push('<line class=\"axis\" x1=\"' + C + '\" y1=\"' + C + '\" x2=\"' + x1.toFixed(1) + '\" y2=\"' + y1.toFixed(1) + '\"/>');\n      var r = items[i].ratio === null ? 0 : items[i].ratio;\n      var px = C + Math.cos(ang) * R * r;\n      var py = C + Math.sin(ang) * R * r;\n      poly.push(px.toFixed(1) + ',' + py.toFixed(1));\n      dots.push('<circle class=\"radar-dot\" cx=\"' + px.toFixed(1) + '\" cy=\"' + py.toFixed(1) + '\" r=\"2.4\"/>');\n      var lx = C + Math.cos(ang) * (R + 15);\n      var ly = C + Math.sin(ang) * (R + 15);\n      var anchor = Math.abs(lx - C) < 6 ? 'middle' : (lx > C ? 'start' : 'end');\n      parts.push('<text class=\"lbl\" x=\"' + lx.toFixed(1) + '\" y=\"' + (ly + 4).toFixed(1) + '\" text-anchor=\"' + anchor + '\">' + esc(items[i].subject) + '</text>');\n    }\n    return '<svg class=\"radar\" viewBox=\"0 0 240 240\" width=\"240\" height=\"240\" role=\"img\" aria-label=\"各科得分率雷达图\">'\n      + parts.join('')\n      + '<polygon class=\"radar-poly\" points=\"' + poly.join(' ') + '\"/>'\n      + dots.join('')\n      + '</svg>';\n  }\n\n  function subjectTable(rows, srcLabel) {\n    var items = withRatio(rows.slice().sort(function (p, q) {\n      var ip = SUBJECT_ORDER.indexOf(p.subject);\n      var iq = SUBJECT_ORDER.indexOf(q.subject);\n      if (ip < 0) ip = 50;\n      if (iq < 0) iq = 50;\n      return ip - iq;\n    }));\n\n    // 求和 / 雷达只用核心科目：合成科目（史地政等）与总分行是派生值，重复计入会翻倍\n    var isAggName = function (n) { return /史地政|理综|文综|总分|合计|总计/.test(String(n || '')); };\n    var core = items.filter(function (x) { return !isAggName(x.subject); });\n    var total = 0;\n    var totalFull = 0;\n    var summable = true;\n    core.forEach(function (it) {\n      if (it.full && isFinite(parseFloat(it.score))) { total += parseFloat(it.score); totalFull += it.full; }\n      else { summable = false; }\n    });\n    var ratio = summable && totalFull > 0 ? total / totalFull : null;\n\n    var ranked = items.slice().filter(function (x) { return x.ratio !== null; }).sort(function (a, b) { return b.ratio - a.ratio; });\n    ranked.forEach(function (x, i) { x.__rank = i + 1; });\n    // 有得分的按排名从高到低排，没得分的垫后 → 徽章 1..N 顺序递增，不再乱跳\n    var ordered = ranked.concat(items.filter(function (x) { return x.ratio === null; }));\n    var bars = ordered.map(function (it) {\n      var cls = it.ratio === null ? '' : it.ratio >= 0.85 ? 'great' : it.ratio >= 0.7 ? 'good' : it.ratio >= 0.5 ? 'ok' : 'low';\n      var bar = it.ratio === null ? '' : '<div class=\"bar ' + cls + '\"><i style=\"width:' + (it.ratio * 100).toFixed(1) + '%\"></i></div>';\n      var val = it.score === null\n        ? '<span class=\"null\">—</span>'\n        : '<span class=\"score ' + cls + '\">' + esc(it.score) + '</span>' + (it.full ? '<span class=\"null\">/' + it.full + '</span>' : '');\n      return '<div class=\"srow\"><span class=\"rank\">' + (it.__rank || '') + '</span><span class=\"subj\">' + esc(it.subject) + '</span><span class=\"val\">' + val + '</span>' + bar + '</div>';\n    }).join('');\n\n    var head = '<div class=\"detail-head\">'\n      + (ratio === null && !summable ? '' : donutSvg(ratio, round1(total), totalFull || null))\n      + '<div class=\"dh-text\"><div class=\"dh-title\">各科明细 · ' + items.length + ' 科</div>'\n      + '<div class=\"dh-sub\">' + (ratio === null ? '满分未知，暂不计算得分率' : '得分率 ' + Math.round(ratio * 100) + '% · 按得分率排序') + '</div></div>'\n      + (srcLabel ? '<span class=\"src\">' + esc(srcLabel) + '</span>' : '')\n      + '</div>';\n\n    return head\n      + '<div class=\"detail-grid\">'\n      + '<div class=\"viz\">' + radarSvg(core) + '</div>'\n      + '<div><div class=\"subj-grid\">' + bars + '</div>'\n      + '<div class=\"bars-foot\">竖虚线 = 70% 及格参考线 · 条形长度 = 得分率（分数 ÷ 满分）</div></div>'\n      + '</div>';\n  }\n\n  function shotsImportHtml(examId) {\n    return '<div class=\"shots-imp\"><div class=\"shots-h\">没有抓到答题卡图 · 粘贴 DevTools 里的响应（JSON 或 HTML），自动提取图片地址</div>'\n      + '<textarea class=\"imp-ta\" placeholder=\"把 baseInfo 接口的「响应」整段粘到这里，或把答题卡页的 HTML 粘进来\"></textarea>'\n      + '<button class=\"imp-btn\" data-exam=\"' + esc(examId) + '\">解析并保存</button>'\n      + '<span class=\"imp-msg\"></span></div>';\n  }\n\n  function isMarkUrl(u) { return /\\/assets\\/img\\/original_i/.test(String(u)); }\n\n  // 一级菜单：只显示答卷（扣分图层收进 data 属性，点开再看）\n  function marksFor(originals, subj, page) {\n    if (!originals || !originals.length) return [];\n    var hit = originals.filter(function (o) { return (o.subject || '') === subj; })[0]\n      || originals.filter(function (o) { return !o.subject; })[0];\n    if (!hit || !hit.marks) return [];\n    return hit.marks.filter(function (m) { return Number(m.page) === Number(page); });\n  }\n\n  function marksForAll(originals, subj) {\n    if (!originals || !originals.length) return [];\n    var hit = originals.filter(function (o) { return (o.subject || '') === subj; })[0]\n      || originals.filter(function (o) { return !o.subject; })[0];\n    return (hit && hit.marks) ? hit.marks : [];\n  }\n\n  function shotsHtml(list, examId, originals) {\n    if (!list || !list.length) return examId ? shotsImportHtml(examId) : '';\n    var items = list.map(function (x) { return typeof x === 'string' ? { subject: '', url: x } : x; });\n    var order = [];\n    var bySubj = {};\n    items.forEach(function (it) {\n      var k = it.subject || '';\n      if (!bySubj[k]) { bySubj[k] = []; order.push(k); }\n      bySubj[k].push(it.url);\n    });\n    return order.map(function (k) {\n      var all = bySubj[k];\n      var marks = all.filter(isMarkUrl);\n      var scans = all.filter(function (u) { return !isMarkUrl(u); });\n      var show = scans.length ? scans : all;          // 没有答卷时才退回显示图层\n      var cells = show.map(function (u, i) {\n        var src = '/admin/api/image?u=' + encodeURIComponent(u);\n        var data = esc(JSON.stringify(marks.map(function (m) { return '/admin/api/image?u=' + encodeURIComponent(m); })));\n        return '<a class=\"shot\" href=\"' + src + '\" data-marks=\"' + data + '\" data-rects=\"' + esc(JSON.stringify(marksFor(originals, k, i + 1))) + '\" data-rects-all=\"' + esc(JSON.stringify(marksForAll(originals, k))) + '\" data-title=\"' + esc((k || '答题卡') + ' 第' + (i + 1) + '页') + '\" rel=\"noreferrer\">'\n          + '<img src=\"' + src + '\" alt=\"' + esc((k || '答题卡') + ' 第' + (i + 1) + '页') + '\" loading=\"lazy\">'\n          + '<span class=\"shot-i\">' + (i + 1) + '</span>'\n          + (marks.length ? '<span class=\"shot-mark\">批改</span>' : '')\n          + '</a>';\n      }).join('');\n      return '<div class=\"shots-grp\"><div class=\"shots-h\">' + (k ? esc(k) : '答题卡') + ' · ' + show.length + ' 张'\n        + (marks.length ? '（含 ' + marks.length + ' 张扣分图层，点开看合成图）' : '') + '</div>'\n        + '<div class=\"shots\">' + cells + '</div></div>';\n    }).join('');\n  }\n\n  function paperInfoHtml(meta) {\n    if (!meta) return '';\n    var chips = [];\n    if (meta.type) chips.push(['类型', meta.type]);\n    if (meta.date) chips.push(['时间', meta.date]);\n    if (meta.candidates) chips.push(['实考', meta.candidates + ' 人']);\n    if (meta.full) chips.push(['满分', meta.full + ' 分']);\n    if (meta.questions) chips.push(['试题', meta.questions + ' 道']);\n    if (meta.difficulty) chips.push(['难度', meta.difficulty]);\n    if (meta.difficultyRatio) chips.push(['难中易', meta.difficultyRatio]);\n    if (meta.objective) chips.push(['客观题', meta.objective.count + ' 道 / ' + meta.objective.score + ' 分']);\n    if (meta.subjective) chips.push(['主观题', meta.subjective.count + ' 道 / ' + meta.subjective.score + ' 分']);\n    if (!chips.length && !meta.comment) return '';\n    if (meta.papers && meta.papers.length) {\n      var pk = meta.papers.map(function (p) { return (p.courseName || '') + ' #' + p.examPaperId; }).join('、');\n      chips.push(['原卷', pk]);\n    }\n    return '<div class=\"paper\"><div class=\"paper-h\">试卷信息</div><div class=\"paper-grid\">'\n      + chips.map(function (c) { return '<div class=\"pchip\"><span class=\"pk\">' + esc(c[0]) + '</span><span class=\"pv\">' + esc(c[1]) + '</span></div>'; }).join('')\n      + '</div>' + (meta.comment ? '<div class=\"paper-comment\">' + esc(meta.comment) + '</div>' : '') + '</div>';\n  }\n\n  function metaFallbackHtml(txt) {\n    if (!txt) return '';\n    return '<details class=\"paper-raw\"><summary>未识别到试卷信息 · 展开原文（复制给作者校准）</summary><pre class=\"rawjson\">' + esc(txt) + '</pre></details>';\n  }\n\n  var curExamId = null;\n  function CurExamId() { return curExamId; }\n\n  function openLightbox(base, opts) {\n    opts = opts || {};\n    var lb = el('lightbox');\n    if (!lb) {\n      lb = document.createElement('div');\n      lb.id = 'lightbox';\n      lb.className = 'lightbox';\n      lb.innerHTML = '<div class=\"lb-inner\"><button class=\"lb-close\" aria-label=\"关闭\">×</button>'\n        + '<div class=\"lb-title\"></div><div class=\"lb-stage\"></div><div class=\"lb-note\"></div></div>';\n      document.body.appendChild(lb);\n      lb.addEventListener('click', function (ev) {\n        if (ev.target === lb || (ev.target.className || '').indexOf('lb-close') >= 0) lb.classList.remove('open');\n      });\n    }\n    var rects = opts.rects || [];\n    var imgs = opts.images || [];\n    var html = '<div class=\"lb-frame\"><img class=\"lb-base\" src=\"' + base + '\" alt=\"答题卡\">';\n    imgs.forEach(function (m) { html += '<img class=\"lb-over\" src=\"' + m + '\" alt=\"图层\">'; });\n    rects.forEach(function (r) {\n      var pct = function (v) { return (Math.max(0, Math.min(1, Number(v) || 0)) * 100).toFixed(2) + '%'; };\n      html += '<span class=\"lb-mark\" style=\"left:' + pct(r.left) + ';top:' + pct(r.top)\n        + ';width:' + pct(r.width) + ';height:' + pct(r.height) + '\">'\n        + (r.lost ? '<i>-' + r.lost + '</i>' : '') + '</span>';\n    });\n    html += '</div>';\n    lb.querySelector('.lb-stage').innerHTML = html;\n    lb.querySelector('.lb-title').textContent = opts.title || '答题卡';\n    var total = rects.reduce(function (a, r) { return a + (Number(r.lost) || 0); }, 0);\n    lb.querySelector('.lb-note').textContent = rects.length\n      ? ('红框 ' + rects.length + ' 处失分' + (total ? '，合计 -' + Math.round(total * 10) / 10 + ' 分' : '') + '（可按 Esc 或点空白关闭）')\n      : ('本页没有失分标记 · 本页 rects=0；该科共 ' + (opts.debug || '0') + ' 块失分数据');\n    lb.classList.add('open');\n  }\n\n  function detailHtml(d) {\n    if (!d || d.ok === false) {\n      return '<span class=\"err-inline\">取明细失败：' + esc((d && d.error) || 'error') + ' ' + esc((d && d.message) || '') + '</span>';\n    }\n    var paper = paperInfoHtml(d.meta);\n    var fb = paper ? '' : metaFallbackHtml(d.metaText);\n    // 详情接口没带图时，回落到轮询已入库的 state.images（避免白框）\n    var imgs = (d.images && d.images.length) ? d.images : (state && state.images ? state.images[d.examId] : null);\n    var origs = (d.meta && d.meta.originals) || (state && state.meta && state.meta[d.examId] && state.meta[d.examId].info ? state.meta[d.examId].info.originals : null);\n    var shots = shotsHtml(imgs, d.examId, origs);\n    if (d.normalized && d.rows && d.rows.length) return paper + shots + fb + subjectTable(d.rows, SRC_LABEL[d.source] || d.source || '');\n    var keys = (d.keys || []).join(', ');\n    var raw = d.raw ? JSON.stringify(d.raw, null, 1) : '';\n    if (raw.length > 3200) raw = raw.slice(0, 3200) + ' …';\n    return paper + '<div class=\"detail-hint\">接口返回了 ' + esc(String(d.total || 0)) + ' 条，但字段名没对上，解析不出科目/分数。</div>'\n      + (keys ? '<div class=\"detail-hint\">出现的键名：<code>' + esc(keys) + '</code></div>' : '')\n      + (raw ? '<pre class=\"rawjson\">' + esc(raw) + '</pre>' : '');\n  }\n\n  function toggleDetail(row) {\n    var next = row.nextElementSibling;\n    if (next && next.classList && next.classList.contains('detail-row')) {\n      var wrap0 = next.querySelector('.detail-wrap');\n      if (wrap0) wrap0.classList.remove('open');       // 先收高度，再移除节点\n      setTimeout(function () { if (next.parentNode) next.parentNode.removeChild(next); }, 300);\n      return;\n    }\n    var btn = row.querySelector('button.mini');\n    if (!btn) return;\n    var stale = row.nextElementSibling;\n    if (stale && stale.classList && stale.classList.contains('detail-row')) stale.parentNode.removeChild(stale);\n    var examId = btn.getAttribute('data-exam');\n    curExamId = examId;\n    var examTypeId = btn.getAttribute('data-type') || '';\n    var tr = document.createElement('tr');\n    tr.className = 'detail-row';\n    tr.innerHTML = '<td colspan=\"6\"><div class=\"detail-wrap\"><div class=\"detail-inner\">'\n      + '<div class=\"detail-hint\">正在向上游取各科明细…</div>'\n      + '<div class=\"skeleton\" style=\"width:220px\"></div>'\n      + '<div class=\"skeleton\" style=\"width:180px\"></div>'\n      + '<div class=\"skeleton\" style=\"width:200px\"></div>'\n      + '</div></div></td>';\n    row.parentNode.insertBefore(tr, row.nextSibling);\n    var wrap = tr.querySelector('.detail-wrap');\n    var inner = tr.querySelector('.detail-inner');\n    // 轮询时已经把分数与试卷信息存库，这里直接用：零等待、不打上游\n    var dbRows = state && state.subjects ? state.subjects[examId] : null;\n    var dbMeta = state && state.meta ? state.meta[examId] : null;\n    var hasDb = (dbRows && dbRows.length) || dbMeta;\n    if (hasDb) {\n      var storedInfo = dbMeta ? (dbMeta.info || null) : null;\n      var dbShots = state && state.images ? state.images[examId] : null;\n      inner.innerHTML = paperInfoHtml(storedInfo) + shotsHtml(dbShots, examId, storedInfo && storedInfo.originals) + (dbRows && dbRows.length ? subjectTable(dbRows, SRC_LABEL.db) : '');\n      requestAnimationFrame(function () { wrap.classList.add('open'); });\n      return;\n    }\n    requestAnimationFrame(function () { wrap.classList.add('open'); });   // 下一帧再开，保证过渡生效\n    if (detailCache[examId]) { inner.innerHTML = detailCache[examId]; return; }\n    api('/admin/api/detail?examId=' + encodeURIComponent(examId) + '&examTypeId=' + encodeURIComponent(examTypeId)).then(function (r) {\n      if (r.status === 401) { showLogin('会话已过期，请重新输入密码。'); row.parentNode.removeChild(tr); return; }\n      var html = detailHtml(r.body);\n      detailCache[examId] = html;\n      inner.innerHTML = html;\n    }).catch(function (e) {\n      inner.innerHTML = '<span class=\"err-inline\">请求失败：' + esc(String(e)) + '</span>';\n    });\n  }\n\n  el('tbSnap').addEventListener('click', function (ev) {\n    var t = ev.target;\n    var shot = t && t.closest ? t.closest('.shot') : null;\n    if (shot) {\n      ev.preventDefault();\n      var imgs = [];\n      try { imgs = JSON.parse(shot.getAttribute('data-marks') || '[]'); } catch (e) { imgs = []; }\n      var rects = [];\n      try { rects = JSON.parse(shot.getAttribute('data-rects') || '[]'); } catch (e) { rects = []; }\n      var dbg = '0';\n      try {\n        var all = JSON.parse(shot.getAttribute('data-rects-all') || '[]');\n        dbg = String(all.length);\n      } catch (e) { dbg = '?'; }\n      openLightbox(shot.getAttribute('href'), { rects: rects, images: imgs, title: shot.getAttribute('data-title'), debug: dbg });\n      return;\n    }\n    if (t && t.className && String(t.className).indexOf('imp-btn') >= 0) {\n      var box = t.closest ? t.closest('.shots-imp') : null;\n      var ta = box ? box.querySelector('.imp-ta') : null;\n      var msg = box ? box.querySelector('.imp-msg') : null;\n      var examId = t.getAttribute('data-exam');\n      if (!ta || !ta.value.trim()) { if (msg) msg.textContent = '先粘贴内容'; return; }\n      if (msg) msg.textContent = '解析中…';\n      t.disabled = true;\n      api('/admin/api/import-images', { method: 'POST', body: JSON.stringify({ examKey: examId, text: ta.value }) }).then(function (r) {\n        t.disabled = false;\n        if (r.status === 401) { showLogin('会话已过期，请重新输入密码。'); return; }\n        if (!r.body.ok) { if (msg) msg.textContent = '没解析到图片：' + (r.body.hint || r.body.error || ''); return; }\n        if (msg) msg.textContent = '已保存 ' + r.body.count + ' 张';\n        detailCache = {};\n        if (r.body.state) render(r.body.state);\n      }).catch(function (e) { t.disabled = false; if (msg) msg.textContent = '请求失败：' + e; });\n      return;\n    }\n    if (!t || t.tagName !== 'BUTTON') return;\n    var row = t.closest ? t.closest('tr') : null;\n    if (row) toggleDetail(row);\n  });\n\n  // ---------- 按钮 ----------\n  function doLogin() {\n    var pw = el('pw').value;\n    if (!pw) { el('loginErr').textContent = '请输入密码'; return; }\n    busy(el('btnLogin'), true, '验证中…');\n    api('/admin/api/login', { method: 'POST', body: JSON.stringify({ password: pw }) }).then(function (r) {\n      busy(el('btnLogin'), false);\n      if (r.body.ok) { el('pw').value = ''; hideLogin(); loadState(); return; }\n      if (r.body.error === 'too_many_attempts') el('loginErr').textContent = '尝试过多，请 ' + r.body.retryAfter + ' 秒后再试。';\n      else if (r.body.error === 'bad_password') el('loginErr').textContent = '密码不对，还可以再试 ' + r.body.remaining + ' 次。';\n      else el('loginErr').textContent = '登录失败：' + (r.body.message || r.body.error || r.status);\n    }).catch(function (e) { busy(el('btnLogin'), false); el('loginErr').textContent = '请求失败：' + e; });\n  }\n\n  function runNow(btn, path, label) {\n    busy(btn, true, label);\n    banner('正在执行：' + label + '…', false);\n    detailCache = {};\n    api(path, { method: 'POST' }).then(function (r) {\n      busy(btn, false);\n      if (r.status === 401) { showLogin('会话已过期，请重新输入密码。'); return; }\n      if (r.body && r.body.state) render(r.body.state);\n      if (r.body && r.body.run) banner((r.body.run.status === 'ok' || r.body.run.status === 'changed' || r.body.run.status === 'baseline' ? '' : '检查未通过：') + (r.body.run.message || ''), r.body.ok === false);\n    }).catch(function (e) { busy(btn, false); banner('请求失败：' + e, true); });\n  }\n\n  el('btnLogin').addEventListener('click', doLogin);\n  el('pw').addEventListener('keydown', function (e) { if (e.key === 'Enter') doLogin(); });\n  el('btnRefresh').addEventListener('click', function () { detailCache = {}; loadState(); });\n  el('btnPoll').addEventListener('click', function () { runNow(el('btnPoll'), '/admin/api/poll', '检查中…'); });\n  el('btnRelogin').addEventListener('click', function () { runNow(el('btnRelogin'), '/admin/api/relogin', '登录中…'); });\n  el('btnDiag').addEventListener('click', function () {\n    el('diagPanel').classList.remove('hidden');\n    el('diagOut').textContent = '正在诊断…';\n    busy(el('btnDiag'), true, '诊断中…');\n    api('/admin/api/diagnose').then(function (r) {\n      busy(el('btnDiag'), false);\n      if (r.status === 401) { showLogin('会话已过期，请重新输入密码。'); return; }\n      el('diagOut').textContent = JSON.stringify(r.body, null, 2);\n    }).catch(function (e) { busy(el('btnDiag'), false); el('diagOut').textContent = '诊断失败：' + e; });\n  });\n  el('btnLogout').addEventListener('click', function () {\n    api('/admin/api/logout', { method: 'POST' }).then(function () { showLogin('已退出。'); });\n  });\n\n  loadState();\n})();\n</script>\n</body>\n</html>\n";
